import Modal from "flarum/common/components/Modal";
import Link from "flarum/common/components/Link";
import Button from "flarum/common/components/Button";
import LoadingIndicator from "flarum/common/components/LoadingIndicator";
import username from "flarum/common/helpers/username";
import Avatar from "flarum/common/components/Avatar";
import app from "flarum/forum/app";
import viewerToUser from "../utils/viewerToUser";
// A discussion can have hundreds of thousands of viewers, so they are fetched from the API page by page.
export default class PostDiscussionViewsModal extends Modal {
  viewers = new Map();
  offset = 0;
  total = 0;
  loading = false;
  oninit(vnode) {
    super.oninit(vnode);
    const initial = this.attrs.post.discussion()?.uniqueViewers();
    if (initial) this.apply(initial);
    if (!initial || this.hasMore()) this.loadMore();
  }
  hasMore() {
    return this.offset < this.total;
  }
  apply({
    viewers,
    total,
    nextOffset
  }) {
    for (const viewer of viewers) {
      if (!this.viewers.has(viewer.id)) this.viewers.set(viewer.id, viewer);
    }
    this.total = total;
    this.offset = nextOffset;
  }
  className() {
    return "Modal--small";
  }
  title() {
    return app.translator.trans("michaelbelgium-discussion-views.forum.post.modal_title_text");
  }
  content() {
    const names = [...this.viewers.values()].map(viewer => {
      const user = viewerToUser(viewer);
      return m("li", {
        key: viewer.id
      }, m(Link, {
        href: app.route.user(user)
      }, m(Avatar, {
        user: user
      }), username(user)));
    });
    return m("div", {
      className: "Modal-body"
    }, m("ul", {
      className: "PostLikesModal-list"
    }, names), this.loading ? m(LoadingIndicator, null) : this.hasMore() && m(Button, {
      className: "Button Button--block",
      onclick: () => this.loadMore()
    }, app.translator.trans("core.forum.discussion_list.load_more_button")));
  }
  loadMore() {
    const discussion = this.attrs.post.discussion();
    if (!discussion || this.loading) return;
    this.loading = true;
    app.request({
      method: "GET",
      url: `${app.forum.attribute("apiUrl")}/discussions/${discussion.id()}/viewers`,
      params: {
        page: {
          offset: this.offset
        }
      }
    }).then(response => this.apply({
      viewers: response.data,
      ...response.meta
    }))
    // app.request already shows an alert; keep the button so the user can retry.
    .catch(() => {}).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('michaelbelgium-discussion-views', 'forum/components/PostDiscussionViewsModal', PostDiscussionViewsModal);